mapper.select:
SELECT TEMP.ORG_CODE AS ORGCODE, ifnull(INFO.FPROD_ID,INFO.PROD_ID) AS PRODID, TEMP.OPEN_START AS OPENSTART, TEMP.OPEN_END AS OPENEND, INFO.VDATE AS VDATE, INFO.OPERATE_MODE AS OPERATEMODE, code.REG_CODE REGCODE, TEMP.Status FROM ( /**交易**/ SELECT DEAL.ORG_CODE, DEAL.PROD_ID, DEAL.FPROD_ID, (case DEAL.TRADE_TYPE when '04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end) AS OPEN_START, (case DEAL.TRADE_TYPE when '04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end) AS OPEN_END, case when DATE_FORMAT(DEAL.UPDATE_TIME, '%Y-%m-%d') != DATE_FORMAT(DEAL.SETTDATE_DATE, '%Y-%m-%d') and DEAL.Status='E' then 'M' else DEAL.Status end Status FROM CHB_PRD_DEAL DEAL WHERE ( DATE_FORMAT(DEAL.UPDATE_TIME, '%Y-%m-%d') = #{batchDate,jdbcType = VARCHAR} or DATE_FORMAT((case DEAL.TRADE_TYPE when '04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end), '%Y-%m-%d') = #{batchDate,jdbcType = VARCHAR}) AND DEAL.TRADE_TYPE !='01'
AND ifnull(DEAL.FPROD_ID,DEAL.PROD_ID) in
#{accountid}
UNION ALL /**收益率**/ SELECT YIELD.ORG_CODE, YIELD.PROD_ID, YIELD.FPROD_ID, YIELD.CHANGE_DATE AS OPEN_START, YIELD.CHANGE_DATE AS OPEN_END, case when DATE_FORMAT(YIELD.UPDATE_TIME, '%Y-%m-%d') != DATE_FORMAT(YIELD.CHANGE_DATE, '%Y-%m-%d') and YIELD.status='E' then 'M' else YIELD.status end status FROM CHB_PRD_PERIODYIELD YIELD WHERE (DATE_FORMAT(YIELD.UPDATE_TIME, '%Y-%m-%d') = #{batchDate,jdbcType = VARCHAR} or DATE_FORMAT(YIELD.CHANGE_DATE, '%Y-%m-%d') = #{batchDate,jdbcType = VARCHAR})
AND ifnull(YIELD.FPROD_ID,YIELD.PROD_ID) in
#{accountid}
/*起息日当天的不报送*/ AND NOT EXISTS (SELECT 1 FROM CHB_PRD_BASEINFO INFO WHERE INFO.VDATE = YIELD.CHANGE_DATE and ifnull(YIELD.FPROD_ID,YIELD.PROD_ID) = info.prod_id) UNION ALL /**费用**/ SELECT FEEINFO.ORG_CODE, FEEINFO.PROD_ID, FEEINFO.FPROD_ID, FEEINFO.PAY_DATE AS OPEN_START, FEEINFO.PAY_DATE AS OPEN_END, case when DATE_FORMAT(FEEINFO.UPDATE_TIME, '%Y-%m-%d') != DATE_FORMAT(FEEINFO.PAY_DATE, '%Y-%m-%d') and FEEINFO.status='E' then 'M' else FEEINFO.status end status FROM CHB_PRD_FEE_DEAL FEEINFO WHERE ( DATE_FORMAT(FEEINFO.UPDATE_TIME, '%Y-%m-%d') = #{batchDate,jdbcType = VARCHAR} or DATE_FORMAT(FEEINFO.PAY_DATE, '%Y-%m-%d') = #{batchDate,jdbcType = VARCHAR})
AND FEEINFO.FEE_TYPE = '01'
AND ifnull(FEEINFO.FPROD_ID,FEEINFO.PROD_ID) in
#{accountid}
) TEMP INNER JOIN CHB_PRD_BASEINFO INFO ON INFO.PROD_ID = ifnull(TEMP.FPROD_ID,TEMP.PROD_ID)
AND INFO.STATUS != 'D' AND INFO.OPERATE_MODE IN ('01', '02') left join CHB_PRDRESIST_CODE code on code.prodid=ifnull(TEMP.FPROD_ID,TEMP.PROD_ID) GROUP BY TEMP.ORG_CODE, ifnull(INFO.FPROD_ID,INFO.PROD_ID), TEMP.OPEN_START, TEMP.OPEN_END, INFO.VDATE, INFO.OPERATE_MODE, TEMP.Status, code.REG_CODE

select distinct sub.prod_id as prodId from chb_prd_deal_sub sub
where 1=1 and sub.send_status != '01' and sub.mdate = #{batchDate,jdbcType = DATE}
and sub.prod_id in
#{accountid}

select ifnull(deal.fprod_id,deal.prod_id) prodId, deal.org_code orgCode, deal.trade_type tradeType, (case DEAL.TRADE_TYPE when '04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end) payDate, deal.ccy, sum(ifnull(deal.int_amt,0)) intAmt, max(ifnull(deal.unit_bonus_amount,0)) unitBonusAmount, sum(ifnull(deal.trade_qty,0)) tradeQty, sum(ifnull(deal.trade_prince,0)) tradePrince from chb_prd_deal deal
where deal.status != 'D' AND DEAL.TRADE_TYPE !='01' and (deal.BUY_PLACE not in('210200','330200','350200','370200','440300') or deal.BUY_PLACE is null)
ifnull(deal.fprod_id,deal.prod_id) = #{prdDealSub.prodId,jdbcType = VARCHAR}
and (case DEAL.TRADE_TYPE when '04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end)
= #{prdDealSub.openEnd,jdbcType = DATE}
group by ifnull(deal.fprod_id,deal.prod_id), deal.org_code, deal.trade_type, (case DEAL.TRADE_TYPE when '04' then DEAL.INTEREST_DATE else DEAL.SETTDATE_DATE end), deal.ccy

SELECT ifnull(FPROD_ID,PROD_ID) prodId, PROD_NAME prodName, ORG_CODE orgCode, FEE_ID feeId, FEE_NAME feeName, CCY ccy, SUM(ifnull(AMT,0)) amt, PAY_DATE payDate FROM CHB_PRD_FEE_DEAL INFO WHERE INFO.STATUS !='D' AND INFO.FEE_TYPE = '01'
ifnull(info.fprod_id,info.prod_id) = #{prdDealSub.prodId,jdbcType = VARCHAR}
and info.pay_date
= #{prdDealSub.openEnd,jdbcType = DATE}
group by ifnull(FPROD_ID,PROD_ID), PROD_NAME, ORG_CODE, FEE_ID, FEE_NAME, CCY, PAY_DATE

select
yield.prod_value prodValue,yield.ccy
from chb_prd_periodyield yield
where yield.change_date = (select max(change_date)
from chb_prd_periodyield yield1
where yield1.prod_id = yield.prod_id

and yield1.status != 'D'

	and yield1.change_date < #{date,jdbcType = DATE}


	and yield1.change_date <=#{date,jdbcType = DATE}
)
AND yield.prod_id = #{prodId, jdbcType = VARCHAR}

AND 1 = 1 limit 1

SELECT
TDADD_INTAMT tdaddIntamt,
CCY ccy
FROM CHB_PRD_POSITION POS
WHERE POS.CDATE = #{date,jdbcType = DATE}
AND POS.PROD_ID = #{prodId, jdbcType = VARCHAR}
AND POS.CCY =  #{ccy, jdbcType = VARCHAR}

select yield.Unit_Value_Total from chb_prd_periodyield yield where yield.change_date = (select max(change_date) from chb_prd_periodyield yield1 where yield1.prod_id = yield.prod_id
and yield1.status != 'D' and yield1.change_date <=#{date,jdbcType = DATE}) AND yield.prod_id = #{prodId, jdbcType = VARCHAR}
AND 1 = 1 limit 1

select
trade_type  tradeType,
cpp.ccy as valueCcy,
(case SUM(ifnull(REG_TRADE_QTY,0)) when 0 then NULL else (SUM(ifnull(TRADE_QTY,0))*10000/SUM(ifnull(REG_TRADE_QTY,0))) end) AS  shareAmtWan,
(case SUM(ifnull(REG_TRADE_QTY,0)) when 0 then NULL else (SUM(ifnull(INT_AMT,0))*10000/SUM(ifnull(REG_TRADE_QTY,0))) end) AS  cashAmtWan
from  CHB_PRD_BONUS_DEAL
left join(
select prod_id prodId,ccy,prod_value prodValue
from (
select rank() over (partition by prod_id order by change_date desc) my_rank,
prod_id, ccy, prod_value
from CHB_PRD_PERIODYIELD
where CHANGE_DATE <=#{payDate,jdbcType=DATE}
and prod_id = #{prodId, jdbcType = VARCHAR}
and CHANG_TYPE='01'
) aa
where my_rank = 1
)cpp
on CHB_PRD_BONUS_DEAL.PROD_ID = cpp.prodId
where   ifnull(FPROD_ID,PROD_ID)=#{prodId, jdbcType = VARCHAR}
AND  settdate_DATE=#{payDate, jdbcType = DATE}
GROUP BY ifnull(FPROD_ID,PROD_ID),trade_type
